class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        answer = []
        count = 0

        for index, color in queries:
            prev_color = nums[index]
            # Check previous color's contribution
            if prev_color != 0:
                # Check left neighbor
                if index > 0 and nums[index - 1] == prev_color:
                    count -= 1
                # Check right neighbor
                if index < n - 1 and nums[index + 1] == prev_color:
                    count -= 1
            # Update the color
            nums[index] = color
            # Check new color's contribution
            if color != 0:
                # Check left neighbor
                if index > 0 and nums[index - 1] == color:
                    count += 1
                # Check right neighbor
                if index < n - 1 and nums[index + 1] == color:
                    count += 1
            answer.append(count)

        return answer

